import json,pathlib
root=pathlib.Path('/workspace/omega_runtime')
out=[]
for p in sorted(root.rglob('*')):
    try:
        rel=str(p.relative_to(root))
    except Exception:
        continue
    if len(p.parts)-len(root.parts)>3:
        continue
    if p.is_file() and (p.suffix in {'.py','.json','.md'} or 'relay' in p.name.lower() or 'alignment' in p.name.lower()):
        out.append({'path':rel,'bytes':p.stat().st_size})
    if len(out)>=120:
        break
print(json.dumps({'files':out},separators=(',',':')))
